using System;

function parseCsvItem(part: string): int {
    return Int32.Parse(part);
}

function parseCsvIntegers(text: string): int[] {
    const parts = String.Split(text, ",");
    return batch parts as part {
        return parseCsvItem(part);
    };
}

function run(): int[] { return parseCsvIntegers("1, -2, 3"); }

using System.Collections.Generic;

function countValues(values: string[]): Dictionary<string, int> {
    const counts = new Dictionary<string, int>();

    for (const value of values) {
        let previous: int = 0;
        if (counts.ContainsKey(value)) {
            previous = counts[value];
        }
        counts[value] = previous + 1;
    }

    return counts;
}

function run(): Dictionary<string, int> { return countValues(["a", "b", "a"]); }

using System.Collections.Generic;

function collectEvenValues(values: int[]): int[] {
    const result = new List<int>();

    for (const value of values) {
        if (value % 2 === 0) {
            result.Add(value);
        }
    }

    return result.ToArray();
}

function run(): int[] { return collectEvenValues([-2, -1, 0, 1, 2]); }

function hashIntegers(values: int[]): int {
    let hash: int = 0x811c9dc5 | 0;

    for (const value of values) {
        hash = ((hash ^ value) * (0x01000193)) | 0;
    }

    return hash;
}

function run(): int { return hashIntegers([1, 2, 3]); }
